"""Exercise production backup/confirmation functions with mocked Docker calls."""
from pathlib import Path
import subprocess
import unittest

SERVER_SCRIPT = Path(__file__).resolve().parents[4] / "backend/deploy/vps/server.sh"

class ServerBackupTest(unittest.TestCase):
    def run_function(self, body):
        return subprocess.run(
            ["bash", "-c", 'source "$1"\n' + body, "backup-test", str(SERVER_SCRIPT)],
            capture_output=True,
        )

    # Generated by Codex and not thoroughly checked for correctness.
    def test_backup_streams_only_archive_bytes_to_caller(self):
        result = self.run_function(r'''
compose() {
  [[ $* == 'exec -T postgres pg_dump -U postgres -d cftracker -Fc' ]] || exit 99
  printf 'PGDMP\000mock-archive'
}
backup
''')
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, b"PGDMP\x00mock-archive")
        self.assertEqual(result.stderr, b"")

    # Generated by Codex and not thoroughly checked for correctness.
    def test_backup_failure_is_reported_even_after_partial_output(self):
        result = self.run_function("compose() { printf partial; return 23; }\nbackup\n")
        self.assertEqual(result.returncode, 23)
        self.assertEqual(result.stdout, b"partial")

    # Generated by Codex and not thoroughly checked for correctness.
    def test_deploy_requires_confirmation_before_any_deployment_operation(self):
        for arguments in ("", "--unknown", "--local-backup-confirmed extra"):
            with self.subTest(arguments=arguments):
                result = self.run_function('compose() { exit 99; }\ndeploy ' + arguments + '\n')
                self.assertEqual(result.returncode, 1)
                self.assertIn(b"Create and verify a local database backup first", result.stderr)
                self.assertEqual(result.stdout, b"")
